function screenGuide(key,title,index){const s=screenGuides[key];const pages=settingPages[key]||[[key,settingRows[key]||[]]];return `<section class="screen-guide"><div class="screen-guide-heading"><span class="guide-step">${String(index).padStart(2,'0')}</span><div><span class="tiny">МОИ НАСТРОЙКИ · РАЗБОР ВСЕХ ПУНКТОВ</span><h3>${title}</h3></div></div><div class="settings-summary"><p>${s.what}</p>${settingRoutes[key]?`<details><summary>Как я открываю этот раздел</summary><p>${settingRoutes[key][1]}</p><button class="annotated-screen" data-image="assets/roman-${settingRoutes[key][0]}.jpg" aria-label="Увеличить путь к разделу"><img src="assets/roman-${settingRoutes[key][0]}.jpg" alt="Поиск раздела в моих настройках" loading="lazy"></button></details>`:''}</div>${pages.map(([file,rows],n)=>`<div class="screen-guide-grid"><div class="screen-visual"><button class="annotated-screen" data-image="assets/${file==='followers'?'':'roman-'}${file}.jpg" aria-label="Увеличить: ${title}, экран ${n+1}"><img src="assets/${file==='followers'?'':'roman-'}${file}.jpg" alt="${title}, мой экран ${n+1}" loading="lazy"></button><p class="screen-caption">Экран ${n+1} из ${pages.length} · нажми для увеличения</p></div><div class="setting-rows">${rows.map(([name,state,why])=>`<article class="setting-row"><span class="setting-state">${state}</span><h4>${name}</h4><p>${why}</p></article>`).join('')}</div></div>`).join('')}<div class="settings-summary"><div class="guide-result">${icon('check')}<div><b>Моя проверка</b><p>${s.do}</p></div></div>${key==='status'?'':select('setting_'+key,'Моя проверка: '+title,['Проверено','Пункт недоступен','Нужно разобраться'])}</div></section>`}
function visualSettings(){return `<div class="visual-intro"><span class="tiny">ШЕСТЬ ГРУПП НАСТРОЕК · В СВОЁМ ТЕМПЕ</span><h3>Смотри. Сравнивай. Проверяй.</h3><p>Я разбираю каждый видимый пункт: своё значение, назначение и варианты выбора. В длинных разделах показываю продолжение экрана. Нажми на фото, чтобы увеличить его.</p><p class="note">Это мои настройки, а не универсальное условие роста. Я показываю свои экраны; на твоём телефоне названия и доступность пунктов могут отличаться.</p></div>${romanCard('settings-type','Открываю тип аккаунта','В настройках нахожу «Тип аккаунта и инструменты».',55,5)}${romanCard('tools','Перехожу к текущему типу','В этом разделе открываю верхнюю строку «Тип аккаунта». Ниже у меня также видны инструменты, включая пробные Reels.',17,5)}${shots.map(([key,title],j)=>screenGuide(key,title,j+1)).join('')}`}
function profileExample(){return romanCard('profile','Показываю свой профиль','В моём профиле видны имя, описание и кнопка редактирования. Тебе нужно заполнить их своими данными.',24,13)+romanCard('edit-profile','Редактирую имя и описание','Здесь я меняю имя, имя пользователя и биографию. Для своего блога напиши собственное описание - не переноси мои достижения в свой профиль.',27,33)+`<section class="profile-example"><div class="panel-heading"><div><span class="tiny">УЧЕБНЫЙ ПРИМЕР · НЕ СКРИНШОТ INSTAGRAM</span><h3>Дай человеку причину остаться</h3></div>${icon('user')}</div><div class="profile-pair"><div class="profile-sample before"><span class="tiny">НЕТ КОНКРЕТИКИ</span><div class="sample-avatar">А</div><h4>Анна</h4><p>Моя жизнь<br>Люблю всё красивое<br>Добро пожаловать</p><small>Неясно, о чём будут следующие публикации.</small></div><div class="profile-sample after"><span class="tiny">ПОНЯТНЕЕ</span><div class="sample-avatar">А</div><h4>Анна · истории о семье</h4><p>О семье и непростых разговорах.<br>Личный опыт без идеальной картинки.<br>Оставайся, если узнаёшь себя.</p><small>Есть тема, характер подачи и приглашение.</small></div></div><ol class="profile-recipe"><li><b>Тема</b><span>Что человек будет регулярно видеть?</span></li><li><b>Подача</b><span>Чем отличается твой взгляд?</span></li><li><b>Приглашение</b><span>Зачем вернуться к следующим роликам?</span></li></ol><p class="note">Пример вымышленный. Подставь свои темы и опыт; не копируй обещание, которое не собираешься выполнять.</p></section>`}
function firstModuleVisual(i){if(i===0)return `<section class="visual-intro"><span class="tiny">ПЕРЕД ПЕРВЫМ ШАГОМ</span><h3>Выбери рабочую точку старта</h3><div class="account-route"><div>${icon('user')}<b>Есть доступ</b><p>Ты можешь войти в аккаунт и восстановить доступ.</p></div><div>${icon('shield')}<b>Проверка впереди</b><p>Следующим шагом прочитаешь сообщения платформы.</p></div><div>${icon('flag')}<b>Готов публиковать</b><p>Выбран профиль, который будешь вести регулярно.</p></div></div></section>`;if(i===3)return `<section class="visual-intro"><span class="tiny">ДВА ПУТИ · ОБА ДОПУСТИМЫ</span><h3>Что делать со старой лентой</h3><div class="archive-options"><div>${icon('book')}<h4>Оставить</h4><p>Сохрани публикации, которые подходят блогу или важны для тебя.</p></div><div>${icon('archive')}<h4>Архивировать</h4><p>Если решил убрать старое из профиля, проверь название действия: «Архивировать». Не выбирай удаление.</p></div></div><p class="note">Перед изменением прочитай подтверждение в своём приложении. Здесь показана схема выбора, а не расположение кнопок Instagram.</p></section>`;if(i===4)return profileExample();if(i===5)return `<section class="visual-intro"><span class="tiny">ТВОЙ СТАРТОВЫЙ СНИМОК</span><h3>Сохрани то, с чем будешь сравнивать</h3><div class="account-route"><div>${icon('calendar')}<b>Дата</b><p>Когда начинается практика.</p></div><div>${icon('user')}<b>Подписчики</b><p>Фактическое число на эту дату.</p></div><div>${icon('play')}<b>Пробный режим</b><p>Есть, нет или ещё не проверен.</p></div></div><p class="note">Дополнительно сохрани у себя снимок профиля. Не публикуй личные данные и данные восстановления аккаунта.</p></section>`;return ''}

function romanCard(key,title,text,top,height){return `<figure class="screen-guide"><div class="screen-guide-heading"><div><span class="tiny">МОЙ АККАУНТ · ROMANPOPULAR</span><h3>${title}</h3></div></div><div class="screen-guide-grid"><div class="screen-visual"><button class="annotated-screen" data-image="assets/roman-${key}.jpg" aria-label="Увеличить: ${title}"><img src="assets/roman-${key}.jpg" alt="${title}" loading="lazy"><span class="screen-highlight" style="top:${top}%;height:${height}%" aria-hidden="true"></span></button><p class="screen-caption">Нажми, чтобы рассмотреть мой экран</p></div><figcaption><p>${text}</p>${screenMenuNotes(key)}</figcaption></div></figure>`}
const visualBase=firstModuleVisual;
firstModuleVisual=function(i){let v=visualBase(i);if(i===0)v+=romanCard('profile','Начинаю со своего профиля','Я показываю процесс на romanpopular. У себя сначала проверь, что открыт нужный аккаунт. Меню находится справа вверху.',7,4);if(i===1)v+=romanCard('settings-status','Нахожу статус аккаунта','Из меню профиля я перехожу в настройки и прокручиваю до блока «Информация и поддержка». Здесь открываю «Статус аккаунта».',57,5);if(i===3)v+=romanCard('archive-menu','Выбираю архивирование','В меню своей публикации я выбираю «Архивировать», если хочу убрать её из профиля. Пункт «Удалить» внизу - другое действие.',47,6);return v};

