function screenMenuNotes(key){const notes={
'settings-type':[
['Архив','Открывает сохранённые в архиве материалы.'],['Ваши действия','Переход к действиям и активности аккаунта.'],['Уведомления','Настройки оповещений внутри Instagram; состояние здесь не показано.'],['Управление временем','Инструменты контроля времени в приложении.'],['Instagram для iPad','Отдельный пункт про приложение для iPad.'],['Meta Verified','У меня показано «Подписка оформлена». Это не переключатель охватов.'],['Профессиональная панель','Переход к профессиональным инструментам.'],['Тип аккаунта и инструменты','Здесь я открываю текущий тип и доступные инструменты.'],['Платежи за рекламу','Раздел рекламных платежей; открытие меню не запускает оплату.'],['Конфиденциальность аккаунта','У меня видно «Доступен всем»: профиль общедоступный.'],['Близкие друзья','У меня указано 0. Здесь выбирают отдельную аудиторию.'],['Кросспостинг','Отдельный раздел размещения контента между площадками; его значения на снимке не раскрыты.'],['Заблокированные','У меня указано 0. Переход к списку заблокированных аккаунтов.'],['История, прямой эфир и местоположение','Открывает отдельные настройки этих функций. На снимке нет их внутренних значений.']],
'settings-status':[
['Разрешения приложений и сайтов','Переход к доступам внешних приложений и сайтов.'],['Родительский контроль для аккаунтов подростков','Раздел семейного контроля.'],['Заказы и платежи','Раздел заказов и платежей.'],['Помощь','Переход к помощи Instagram.'],['Ассистент поддержки Meta AI','Отдельный вход в помощь через ассистента.'],['Центр конфиденциальности','Информация о конфиденциальности.'],['Статус аккаунта','Здесь я проверяю сообщения об ограничениях.'],['Информация','Информационный раздел приложения.'],['Meta AI','Вход в другой продукт Meta; это не состояние настройки.'],['Threads','Вход в продукт Threads.'],['Edits','Переход к приложению для создания и монтажа видео.'],['Другие продукты Meta','Переход к списку продуктов.']],
'edit-profile':[
['Редактировать фото или аватар','Здесь я меняю изображение профиля.'],['Имя','У меня «Роман Шестаков». Это отображаемое имя.'],['Имя пользователя','У меня romanpopular. Это имя для ссылки и @упоминаний.'],['Биография','На экране счётчик 147 / 150. Я показываю своё описание; напиши своё, с достоверными фактами о себе.'],['Местоимения','Открывает отдельное поле; значение здесь не показано.'],['Пол','У меня указано «Мужчина».'],['Ссылки','Здесь я редактирую ссылки профиля.'],['Баннеры','Отдельное оформление с музыкой, профилями и другими элементами.'],['Изменить порядок публикаций в сетке','Переход к управлению расположением публикаций.'],['Автор ИИ','У меня выключено. Подпись предлагает эту метку для профиля с персоной, сгенерированной ИИ. Это не метка использования ИИ для правки текста.']],
'archive-menu':[
['Сохранить','Сохраняет публикацию в подборку сохранённого.'],['QR-код','Открывает QR-код публикации.'],['Опубликовано на Facebook','На снимке показан этот статус; это не команда новой публикации.'],['Статистика','Открывает показатели публикации.'],['Запретить повторное использование','Действие для конкретного материала; это не общий переключатель аккаунта.'],['Репосты истории','Отдельный пункт меню, отображён серым.'],['Архивировать','Я выбираю это действие, чтобы убрать старую публикацию из профиля без удаления.'],['Скрыть число отметок «Нравится»','Команда скрытия счётчика лайков.'],['Скрыть число поделившихся','Команда скрытия счётчика поделившихся.'],['Выключить комментарии','Команда отключения комментариев для этой публикации.'],['Рекомендуемые товары','Открывает отдельный пункт, связанный с товарами.'],['Создать видео Reels из этой публикации','Переход к созданию ролика на основе публикации.'],['Редактировать','Открывает редактирование публикации.'],['Настроить предпросмотр','Переход к настройке её отображения.'],['Прикрепить к основной сетке','Команда прикрепления к основной сетке.'],['Удалить','Отдельное действие удаления. Для моего шага архивирования я его не выбираю.']],
'profile':[
['Меню справа вверху','Отсюда я открываю настройки.'],['Публикации, подписчики, подписки','На снимке 3 459 публикаций, 228 тыс. подписчиков и 3 подписки. Это показатели на момент снимка, не цель для первого дня.'],['Описание и ссылка','Я объясняю, чем занимаюсь, и показываю ссылку. Для своего аккаунта используй собственные факты и адрес.'],['Ваша панель','На моём снимке 23,2 млн просмотров за последние 30 дней. Это мой результат за указанный период.'],['Редактировать профиль','Открывает поля имени, описания и оформления.'],['Поделиться профилем','Открывает способы поделиться профилем.'],['Добавьте баннеры','Переход к добавлению баннеров.'],['Актуальные истории','Кружки «Добавить», «КОНТЕНТ…», «Вопросы», «Завод», «Система» - материалы профиля, а не переключатели.'],['Вкладки и нижняя навигация','Сетка, Reels, репосты, отметки и кнопки приложения переключают разделы. Их не нужно «включать» для настройки аккаунта.']]
};notes.tools=[['Тип аккаунта','У меня профессиональный. Открываю строку для подробностей.'],...['Статистика','Запланированный контент','Пробные видео Reels','Live','Каналы','Брендированный контент','Partnership ads','Рекламные инструменты','Монетизация','Инструменты для обмена сообщениями','Другое'].map(x=>[x,'Отдельный вход в инструмент «'+x+'». На этом снимке видно наличие пункта, а не его внутренние настройки или факт использования.'])];const rows=notes[key];return rows?`<details class="screen-menu-notes"><summary>Все остальные пункты этого экрана</summary><p>Я отдельно отмечаю поля, показатели и переходы: у них не всегда есть состояние «включено» или «выключено».</p>${rows.map(([n,t])=>`<article class="setting-row"><h4>${n}</h4><p>${t}</p></article>`).join('')}</details>`:''}

function accountsCenterGuide(){return `<section class="screen-guide"><div class="screen-guide-heading"><span class="guide-step">00</span><div><span class="tiny">ПОДГОТОВКА АККАУНТА</span><h3>Проверяю Центр аккаунтов</h3></div></div><div class="screen-guide-grid"><div class="screen-visual"><button class="annotated-screen account-markup" data-image="assets/roman-accounts-center.jpg" aria-label="Увеличить: мой Центр аккаунтов"><img src="assets/roman-accounts-center.jpg" alt="Мой Центр аккаунтов: один Instagram, WhatsApp, Facebook и Threads" loading="lazy"><span class="account-outline account-primary" aria-hidden="true"><b>1</b></span><span class="account-outline account-other" aria-hidden="true"><b>2</b></span></button><p class="screen-caption">1 - единственный Instagram. 2 - другие сервисы, их можно оставить. Нажми, чтобы открыть оригинал без отметок.</p></div><div><p><b>В моём методе я оставляю в одном Центре только один аккаунт Instagram - тот, который развиваю.</b> Если аккаунтов Instagram несколько, я рекомендую разъединить их. Один Facebook, Threads и WhatsApp могут оставаться связанными, как на моём примере.</p><article class="setting-row"><h4>Instagram · romanpopular</h4><p>Это единственный аккаунт Instagram в моём списке. Считай строки с названием сервиса Instagram, а не все профили подряд.</p></article><article class="setting-row"><h4>WhatsApp</h4><p>Связанный профиль другого сервиса. Это не второй аккаунт Instagram.</p></article><article class="setting-row"><h4>Facebook · Роман Популярный</h4><p>В моём Центре также есть один Facebook. По моей схеме его можно оставить.</p></article><article class="setting-row"><h4>Threads · romanpopular</h4><p>Здесь показан профиль Threads с тем же именем. Я не считаю его дополнительным аккаунтом Instagram.</p></article><article class="setting-row"><h4>Добавить аккаунты</h4><p>Это кнопка добавления. Для выполнения этого шага я не добавляю ещё один Instagram.</p></article></div></div><div class="settings-summary"><h4>Как я разъединяю аккаунты</h4><p>На моём скрине уже оставлен один Instagram, поэтому здесь ничего разъединять не нужно. Следующие действия нужны, если у тебя в списке несколько Instagram.</p><ol class="unlink-steps"><li><b>Проверяю доступ.</b> Убеждаюсь, что знаю данные для отдельного входа в аккаунт, который хочу отвязать, и имею доступ к почте или телефону для восстановления. Если аккаунты используют общий вход, сначала настраиваю отдельный пароль.</li><li><b>Открываю Центр аккаунтов.</b> В Instagram перехожу в свой профиль, нажимаю меню с тремя полосками справа сверху и выбираю «Центр аккаунтов».</li><li><b>Открываю «Управление аккаунтами».</b> Этот пункт находится внизу главной страницы Центра аккаунтов — я выделил его на первом снимке.</li><li><b>Нажимаю «Управлять» в блоке Instagram.</b> Затем сверяю имя нужного профиля. На моём примере показан romanpopular; у тебя нужно выбрать тот Instagram, который хочешь перенести.</li><li><b>Выбираю «Перенести аккаунт из этого Центра аккаунтов».</b> Этот пункт предлагает перенести Instagram в новый Центр аккаунтов. Дальше внимательно читаю условия и следую подсказкам приложения. Следующие экраны подтверждения здесь не показаны.</li><li><b>Проверяю результат.</b> Возвращаюсь к списку: оставляю один Instagram по моей схеме. Отвязанный аккаунт продолжает существовать, в него можно войти отдельно. Если лишних Instagram несколько, повторяю для каждого.</li></ol><div class="transfer-gallery"><article class="transfer-card"><h4>1. Открываю управление аккаунтами</h4><button class="annotated-screen account-markup" data-image="assets/roman-center-menu.jpg" aria-label="Увеличить: Открываю управление аккаунтами"><img src="assets/roman-center-menu.jpg" alt="Открываю управление аккаунтами" loading="lazy"><span class="account-outline account-primary" style="left:3.7%;width:92.6%;top:80.8%;height:5.9%" aria-hidden="true"><b>1</b></span></button><p>На главной странице Центра нажимаю «Управление аккаунтами».</p></article><article class="transfer-card"><h4>2. Выбираю Instagram</h4><button class="annotated-screen account-markup" data-image="assets/roman-account-management-private.png" aria-label="Увеличить: Выбираю Instagram"><img src="assets/roman-account-management-private.png" alt="Выбираю Instagram" loading="lazy"><span class="account-outline account-primary" style="left:67%;width:26%;top:35%;height:4.1%" aria-hidden="true"><b>2</b></span></button><p>Нажимаю «Управлять» именно в блоке Instagram. На моём примере Instagram один; переноси дополнительный профиль только после проверки его имени.</p></article><article class="transfer-card"><h4>3. Переношу аккаунт в отдельный Центр</h4><button class="annotated-screen account-markup" data-image="assets/roman-account-transfer.jpg" aria-label="Увеличить: Переношу аккаунт в отдельный Центр"><img src="assets/roman-account-transfer.jpg" alt="Переношу аккаунт в отдельный Центр" loading="lazy"><span class="account-outline account-primary" style="left:3.7%;width:92.6%;top:31.2%;height:11.1%" aria-hidden="true"><b>3</b></span></button><p>Выбираю «Перенести аккаунт из этого Центра аккаунтов». Пункт «Деактивация или удаление» для этой задачи не нужен.</p></article></div><div class="unlink-warning"><b>Разъединить - значит убрать связь.</b><p>Я не захожу в «Деактивация или удаление» и не подтверждаю удаление профиля, публикаций или данных. Если вижу именно такое предупреждение, возвращаюсь назад.</p></div><details><summary>Не вижу нужной кнопки или не знаю пароль</summary><p>Я не продолжаю наугад. Возвращаюсь на главную страницу Центра и ищу управление аккаунтами. Если отдельного пароля нет, сначала восстанавливаю доступ. Выход из аккаунта на телефоне сам по себе не разъединяет аккаунты в Центре.</p></details><details><summary>Почему я выделяю это отдельным шагом</summary><p>Это организационное правило моего метода. Meta допускает объединение нескольких аккаунтов и позволяет держать их раздельно. Я не утверждаю, что несколько Instagram в одном Центре сами по себе нарушают правила или автоматически снижают охваты.</p><p><a href="https://about.fb.com/news/2023/01/centralizing-apps-settings-in-accounts-center/" target="_blank" rel="noopener">Meta о совместном и раздельном Центре аккаунтов</a></p></details><p class="note">На скринах я показываю путь до переноса в новый Центр. В другой версии приложения названия пунктов могут отличаться. Если видишь предложение удалить аккаунт целиком, вернись назад.</p>${select('accountsCenterReview','Мой Центр аккаунтов',['Один Instagram, проверено','Несколько Instagram, разберусь со связями','Не могу найти раздел'])}<p class="note">Ответ сохранится автоматически. Если пока не можешь проверить связи, продолжай читать и вернись к этому пункту позже.</p></div></section>`}
